// Destination-based road trips. No random placement or per-frame route searches.
export const roadPoint=i=>({x:(i%48+.5)*4-96,z:(Math.floor(i/48)+.5)*4-96});
export function outsidePortals(world){return world.tiles.flatMap((t,i)=>{const x=i%48,y=Math.floor(i/48);if(t.type!=='road'||x!==0&&x!==47&&y!==0&&y!==47)return[];const direction=x===0?[-1,0]:x===47?[1,0]:y===0?[0,-1]:[0,1],p=roadPoint(i);return[{id:i,...p,dx:direction[0],dz:direction[1],outside:{x:p.x+direction[0]*80,z:p.z+direction[1]*80}}];});}
const neighbors=i=>[i%48>0?i-1:-1,i%48<47?i+1:-1,i>=48?i-48:-1,i<2256?i+48:-1].filter(i=>i>=0);
export class Traffic {
 constructor(world,engine){this.engine=engine;this.agents=[];this.sequence=0;this.spawnClock=0;this.completed=0;this.rebuild(world);}
 rebuild(world){this.world=world;this.portals=outsidePortals(world);this.graph=new Map();this.samples=new Map();this.positions=new Map();
 for(const path of world.roadPaths||[]){const samples=this.engine.sampleRoad(path.controls).map(p=>({x:(p.x+.5)*4-96,z:(p.y+.5)*4-96}));const mapping=new Map();for(const i of path.tiles){const p=roadPoint(i);let best=0,d=Infinity;samples.forEach((s,j)=>{const v=(s.x-p.x)**2+(s.z-p.z)**2;if(v<d){d=v;best=j}});mapping.set(i,best);if(!this.positions.has(i))this.positions.set(i,samples[best]);}this.samples.set(path.id,{samples,mapping});}
 for(let i=0;i<world.tiles.length;i++)if(world.tiles[i].type==='road'){const t=world.tiles[i];this.graph.set(i,neighbors(i).filter(j=>{if(world.tiles[j].type!=='road')return false;if(!this.engine.ROADS[t.roadType]?.oneway)return true;for(const id of t.pathIds||[]){const map=this.samples.get(id)?.mapping;if(map?.has(j))return map.get(j)>map.get(i);}return j>i;}));}
 this.trips=[];const pathsFrom=new Map(this.portals.map(p=>[p.id,this.search(p.id)]));
 for(let i=0;i<world.tiles.length;i++){const tile=world.tiles[i];if(!['residential','commercial','industrial','office'].includes(tile.type)||!tile.level||tile.construction)continue;const frontage=neighbors(i).filter(j=>this.graph.has(j)),lotPoint=roadPoint(i),nearest=[...this.portals].sort((a,b)=>Math.hypot(a.x-lotPoint.x,a.z-lotPoint.z)-Math.hypot(b.x-lotPoint.x,b.z-lotPoint.z));let found=false;for(const portal of nearest){const parents=pathsFrom.get(portal.id);for(const road of frontage){const inbound=this.trace(parents,road);if(!inbound)continue;const outwardParents=this.search(road);for(const exit of nearest){const outbound=this.trace(outwardParents,exit.id);if(!outbound)continue;const incoming=this.route(inbound,portal,true),outgoing=this.route(outbound,exit,false),lot=roadPoint(i),stop={x:(lot.x+incoming.at(-1).x)/2,z:(lot.z+incoming.at(-1).z)/2};this.trips.push({destination:i,kind:tile.type==='industrial'?'Delivery':tile.type==='residential'?'Resident visit':'Business visit',inbound:[...incoming,stop],outbound:[stop,...outgoing],cells:[inbound,outbound],roads:new Set([...inbound,...outbound])});found=true;break;}if(found)break;}if(found)break;}}
 // Keep valid trips across additions. Removed roads cancel only affected trips.
 for(const a of this.agents)if(a.active&&(!world.tiles[a.trip.destination]?.level||a.trip.cells.some(cells=>cells.some((i,k)=>!this.graph.has(i)||k<cells.length-1&&!this.graph.get(i).includes(cells[k+1])))))a.active=false;
 }
 search(start){const parents=new Map([[start,null]]),queue=[start];for(let k=0;k<queue.length;k++)for(const n of this.graph.get(queue[k])||[])if(!parents.has(n)){parents.set(n,queue[k]);queue.push(n)}return parents;}
 trace(parents,end){if(!parents.has(end))return null;const path=[];for(let i=end;i!==null;i=parents.get(i))path.push(i);return path.reverse();}
 route(cells,portal,incoming){const points=[];for(let k=0;k<cells.length;k++){const i=cells[k],j=cells[k+1];points.push(this.positions.get(i)||roadPoint(i));if(j===undefined)continue;for(const id of this.world.tiles[i].pathIds||[]){const path=this.samples.get(id);if(!path?.mapping.has(j))continue;const a=path.mapping.get(i),b=path.mapping.get(j),step=b>=a?1:-1;for(let n=a+step;step>0?n<b:n>b;n+=step)points.push(path.samples[n]);break;}}
 if(incoming)points.unshift(portal.outside,{x:portal.x+portal.dx*3,z:portal.z+portal.dz*3});else points.push({x:portal.x+portal.dx*3,z:portal.z+portal.dz*3},portal.outside);
 return points.map((p,i)=>{const a=points[Math.max(0,i-1)],b=points[Math.min(points.length-1,i+1)],dx=b.x-a.x,dz=b.z-a.z,l=Math.hypot(dx,dz)||1;return{x:p.x-dz/l*.48,z:p.z+dx/l*.48}});
 }
 addAgent(){const a={active:false,x:0,z:0,heading:0};this.agents.push(a);return a;}
 begin(a){if(!this.trips.length)return false;const trip=this.trips[this.sequence++%this.trips.length],start=trip.inbound[0];if(this.agents.some(b=>b!==a&&b.active&&Math.hypot(b.x-start.x,b.z-start.z)<3))return false;Object.assign(a,{active:true,trip,phase:'inbound',points:trip.inbound,segment:0,distance:0,dwell:0,x:start.x,z:start.z});return true;}
 update(dt){this.spawnClock+=dt;if(this.spawnClock>=2){const free=this.agents.find(a=>!a.active);if(free&&this.begin(free))this.spawnClock=0;else this.spawnClock=Math.min(this.spawnClock,2);}
 for(const a of this.agents){if(!a.active)continue;if(a.dwell>0){a.dwell-=dt;if(a.dwell<=0){a.phase='outbound';a.points=a.trip.outbound;a.segment=0;a.distance=0;}continue;}
 const forward={x:Math.sin(a.heading),z:Math.cos(a.heading)};if(this.agents.some(b=>b!==a&&b.active&&!b.dwell&&Math.cos(b.heading-a.heading)>.5&&Math.hypot(b.x-a.x,b.z-a.z)<1.8&&(b.x-a.x)*forward.x+(b.z-a.z)*forward.z>.1))continue;
 let move=dt*5;while(move>0&&a.active){const p=a.points[a.segment],q=a.points[a.segment+1];if(!q){if(a.phase==='inbound')a.dwell=4;else{a.active=false;this.completed++;}break;}const length=Math.hypot(q.x-p.x,q.z-p.z);if(length<.001){a.segment++;continue;}const step=Math.min(move,length-a.distance);a.distance+=step;move-=step;const f=a.distance/length;a.x=p.x+(q.x-p.x)*f;a.z=p.z+(q.z-p.z)*f;a.heading=Math.atan2(q.x-p.x,q.z-p.z);if(a.distance>=length-1e-6){a.segment++;a.distance=0;}}}
 }
 get active(){return this.agents.filter(a=>a.active).length;}
}
